mapper.select:
SELECT * FROM product_variants
WHERE product_id = #{productId}
ORDER BY created_at ASC

SELECT EXISTS(
    SELECT 1 FROM product_variants
    WHERE sku_code = #{skuCode}

        AND id != #{excludeId}

)

SELECT pv.* FROM product_variants pv JOIN products p ON p.id = pv.product_id WHERE 1=1
AND p.category_id = #{categoryId}
AND p.ocop_star = CAST(REPLACE(#{ocopRating}, 'OCOP_', '') AS INT)
AND pv.listing_status = 'ACTIVE' AND p.approval_status = 'APPROVED' AND p.listing_status = 'ACTIVE'
ORDER BY pv.created_at ASC LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE product_variants SET
    listing_status = #{listingStatus}::variant_listing_status,
    version        = version + 1,
    updated_at     = NOW()
WHERE id = #{id}
  AND version = #{expectedVersion}
